-- Cogni v0.14 — curated audience-native daily challenge families.
-- Adds five deliberately different challenge families per audience while retaining the wider fallback bank.

create temporary table tmp_v014_curated_challenge(
 content_key text,audience text,title text,prompt text,options jsonb,interaction_type text,
 interaction_config jsonb,correct_index int,correct_answer jsonb,difficulty int,scenario text,
 category text,skill_slug text,explanation text,principle text,application text,
 function_tags text[],goal_tags text[],complexity smallint
) on commit drop;

insert into tmp_v014_curated_challenge values
('v014_uni_source_chain','university_student','The source behind the source','Your essay cites a news article that cites a survey commissioned by the company whose product the article praises. What should you check first?','["Whether the news site has a professional logo","The original survey method, sample and sponsor before treating the result as independent evidence","Whether the article is longer than competing articles","Whether the company has a university graduate scheme"]','single_choice','{}',1,'1',45,'University • Essay research','essay and sources','source-quality','The news article is one step removed from evidence produced by an interested party.','Follow the evidence chain to the source that produced the data and check its incentives and method.','This helps you use AI and secondary sources without accidentally laundering weak evidence into assessed work.',array['study_research'],array['academic_performance'],2),
('v014_uni_health_claim','university_student','The viral wellness claim','A viral video says a supplement “doubles concentration” because 18 students who tried it reported feeling more focused. Choose the TWO checks that matter most.','["Look for a controlled study with a larger and relevant sample","Check whether the creator has more than 100,000 followers","Ask whether placebo effects and self-selection could explain the reports","See whether the video has positive comments"]','multi_select','{}',null,'[0,2]',46,'University • Social media wellness claim','health and misinformation','evidence-evaluation','A tiny self-selected set of testimonials cannot isolate the supplement’s effect.','Prefer evidence designed to test the claim and look for plausible alternative explanations.','This protects everyday decisions from persuasive health claims that AI or social media may repeat without context.',array['study_research'],array['critical_thinking_general','make_better_decisions'],2),
('v014_uni_internship_choice','university_student','Two internships, different trade-offs','You have two internship offers: one has a famous brand but repetitive work; the other has better learning and responsibility but less prestige. Rank the decision steps from strongest to weakest.','["List what you want to learn and what matters for your next step, then compare both offers against those criteria","Ask friends which company name sounds more impressive","Choose the offer that arrived first so you stop worrying","Compare the actual work, manager, learning, constraints and future options"]','ranking','{}',null,'[0,3,1,2]',47,'University • Internship decision','career choice','decision-uncertainty','Clear criteria and real role information are more useful than prestige or arbitrary shortcuts.','When no option is perfect, make the trade-offs explicit and compare what matters to you.','This is the same decision skill you will use for graduate roles, modules and other uncertain choices.',array['study_research'],array['graduate_readiness','make_better_decisions'],2),
('v014_uni_group_project','university_student','What is fact and what is assumption?','Your group wants to say its prototype “will improve student wellbeing” after six classmates say they like it. Sort each statement.','["Six classmates said they liked the prototype","Students who like the prototype will use it regularly","Regular use will improve wellbeing","The feedback came from classmates who already knew the team"]','classification','{"categories":[{"id":"evidence","label":"Evidence we have"},{"id":"assumption","label":"Assumption"}]}',null,'{"0":"evidence","1":"assumption","2":"assumption","3":"evidence"}',45,'University • Group project','group work','assumption-identification','The group has preference feedback, but the chain from liking to use to wellbeing contains untested assumptions.','Separate what you observed from what must be true for the conclusion to follow.','This makes presentations and AI-assisted project claims more credible without making them less ambitious.',array['study_research'],array['academic_performance','critical_thinking_general'],2),
('v014_uni_ai_integrity','university_student','AI rewrote more than you expected','You ask AI to improve the structure of your paragraph. It adds two new factual claims and a citation. What would you do next?','["Submit it because you only asked for editing","Remove the citation but keep the claims","Check the new claims and source, rewrite in your own voice, and make sure the use fits your course rules","Ask AI to make the paragraph sound less like AI"]','triage','{}',2,'2',46,'University • AI-assisted assignment','academic integrity','ai-trust-boundaries','The AI has moved from editing into content creation, which changes both verification and academic-integrity risk.','Notice when an AI task crosses a boundary and increase human checking accordingly.','This lets you use AI productively for study without outsourcing accountability for your submitted work.',array['study_research'],array['work_effectively_with_ai','academic_performance'],2),

('v014_grad_vague_request','graduate_early_career','“Can you sort this out?”','A senior colleague forwards a messy spreadsheet and says, “Can you sort this out for the client by 3?” You do not know the decision it needs to support. What should you do next?','["Start formatting immediately so you look responsive","Ask what the client needs to decide, what output is expected and which assumptions must not change, then confirm timing","Forward it to another graduate","Wait until the senior colleague asks for an update"]','triage','{}',1,'1',50,'Graduate • Vague instruction','ambiguous request','problem-framing','A fast answer to the wrong task is not good execution.','Clarify the decision, outcome and constraints before optimising the deliverable.','This is how early-career professionals become known for understanding the purpose of work, not just completing tasks.',array['general_professional'],array['progress_faster','build_professional_judgement'],2),
('v014_grad_meeting_question','graduate_early_career','Speak up without derailing the meeting','A proposal relies on a number you think may exclude an important customer group. Rank the ways to raise it.','["Could we check whether that figure includes the enterprise customers? If not, it may change the comparison.","That number is wrong.","Stay silent and message a colleague afterwards","Ask five broad questions about the whole proposal so the issue is less direct"]','ranking','{}',null,'[0,3,2,1]',51,'Graduate • Team meeting','speaking up','better-questions','A specific, decision-relevant question can challenge evidence without pretending you already know the answer.','Ask the smallest question that can materially change the decision.','This builds professional confidence without confusing confidence with certainty.',array['general_professional'],array['communicate_with_confidence','progress_faster'],3),
('v014_grad_workload','graduate_early_career','Everything is “urgent”','Three people give you work due today and each says theirs is urgent. Choose the TWO pieces of information that most help you prioritise.','["Which task has the loudest stakeholder","What happens if each task is late and which deadlines are genuinely fixed","Which task you personally enjoy most","How long each task will take and whether scope or timing can be negotiated"]','multi_select','{}',null,'[1,3]',49,'Graduate • Competing deadlines','workload management','missing-information','Urgency becomes useful only when you connect deadlines to consequences, effort and flexibility.','Prioritise using consequence, timing and constraints rather than volume or seniority alone.','This helps you manage workload professionally and have better conversations when demand exceeds capacity.',array['general_professional'],array['progress_faster','build_professional_judgement'],2),
('v014_grad_mistake','graduate_early_career','You find your own mistake','You notice a calculation error in analysis already sent to your manager. Sort each response by whether it strengthens or weakens professional credibility.','["Tell your manager promptly, explain the impact and send a corrected version","Quietly fix your working file and hope the old version is not used","Check the size of the error before explaining how it affects the conclusion","Blame the source data before checking whether that is true"]','classification','{"categories":[{"id":"strengthens","label":"Strengthens credibility"},{"id":"weakens","label":"Weakens credibility"}]}',null,'{"0":"strengthens","1":"weakens","2":"strengthens","3":"weakens"}',50,'Graduate • Correcting a mistake','professional credibility','critical-thinking','Credibility grows when you surface errors proportionately and explain what changes.','Own the evidence, correct it early and distinguish the error from its decision impact.','AI can make errors faster too; professional judgement includes noticing, correcting and communicating them.',array['general_professional'],array['communicate_with_confidence','build_professional_judgement'],2),
('v014_grad_ai_analysis','graduate_early_career','The confident dashboard explanation','AI says sales fell because “customer sentiment weakened”, but the dashboard contains no sentiment data. What should you do?','["Use the explanation because it sounds commercially plausible","Present the sales decline as fact but label the cause as a hypothesis until evidence tests it","Ask AI to make the explanation more concise","Replace the cause with a different plausible story"]','single_choice','{}',1,'1',50,'Graduate • AI-assisted analysis','AI analysis','ai-output-verification','The sales decline may be observed; the proposed cause is an unsupported explanation.','Separate what the data shows from the story used to explain it.','This prevents polished AI wording becoming unearned confidence in presentations and meetings.',array['general_professional'],array['work_effectively_with_ai','analyse_information'],3),

('v014_junior_incident','junior_professional','The incident “root cause”','A service failed shortly after a software release, but monitoring also shows a database capacity spike. Rank the next steps.','["Reconstruct the timeline and test both release and capacity hypotheses against logs","Rollback the release immediately and call it the root cause","Check whether the same failure signature existed before the release","Write the incident report around the explanation senior stakeholders already expect"]','ranking','{}',null,'[0,2,1,3]',58,'Junior professional • Technical incident','root-cause analysis','logical-reasoning','Timing makes the release a plausible cause, not a proven one.','Treat root cause as a hypothesis to test against evidence and alternatives.','This is the same discipline that makes technical recommendations resilient under senior scrutiny.',array['technology_engineering'],array['analyse_information','build_professional_judgement'],3),
('v014_junior_marketing','junior_professional','The campaign winner','Variant B converts better than A after three days, but B received more mobile traffic and a different customer mix. Choose the TWO strongest next steps.','["Check whether randomisation or segment balance was preserved","Declare B the winner before the effect disappears","Compare results within relevant segments or rerun a controlled test","Choose the prettier creative because the numbers are contaminated"]','multi_select','{}',null,'[0,2]',57,'Junior professional • Campaign test','experiment quality','correlation-causation','Unequal traffic mix can create an apparent winner that is not caused by the variant.','Before attributing an outcome to a change, test whether the comparison is fair.','This turns marketing metrics into defensible recommendations rather than attractive post-hoc stories.',array['marketing'],array['analyse_information','make_recommendations'],3),
('v014_junior_hiring','junior_professional','Evidence in the shortlist','A hiring panel discusses four facts about a candidate. Sort each as job-relevant evidence or a weak proxy.','["Performance on a work sample similar to the role","Worked for a famous company","Structured interview evidence against defined criteria","Went to the same university as a senior interviewer"]','classification','{"categories":[{"id":"evidence","label":"Job-relevant evidence"},{"id":"proxy","label":"Weak proxy"}]}',null,'{"0":"evidence","1":"proxy","2":"evidence","3":"proxy"}',56,'Junior professional • Recruitment decision','people evidence','bias-recognition','Prestige and familiarity can feel informative while adding little direct evidence about the work.','Prefer evidence tied to the decision criteria over status or similarity proxies.','This helps professionals challenge biased reasoning constructively even when they are not the final decision-maker.',array['people_hr'],array['build_professional_judgement'],3),
('v014_junior_forecast','junior_professional','The forecast you have to defend','Your forecast assumes margin will recover next quarter because productivity improved for one month, but unresolved claims could offset the gain. What would you do next?','["Use the single best estimate because ranges look indecisive","Show the base case plus the assumptions carrying it, test a downside where claims crystallise, and explain what would change your recommendation","Remove the claims from the analysis because they are uncertain","Use last year’s margin so the forecast has a stable anchor"]','triage','{}',1,'1',59,'Junior professional • Forecast recommendation','forecast and assumptions','assumption-identification','The recommendation depends on both persistence of productivity and treatment of unresolved claims.','Make the assumptions carrying the conclusion visible and test the ones that can change the decision.','This is how a professional turns analysis into a recommendation that senior stakeholders can interrogate and trust.',array['finance_commercial'],array['make_recommendations','manage_upwards'],3),
('v014_junior_client_claim','junior_professional','The client’s “guaranteed” saving','A proposal says a change will save the client 20% because one previous client achieved 22%. Which response is strongest?','["Use 20% because it is already lower than the case study","Describe the case study as evidence of possibility, then model the current client’s drivers and range before committing to a benefit","Remove all benefit estimates to avoid risk","Use 22% so the evidence and claim match"]','single_choice','{}',1,'1',57,'Junior professional • Client proposal','client recommendation','evidence-evaluation','A single case study shows what happened somewhere else, not what this client will necessarily achieve.','Translate evidence into the current decision rather than copying a result across contexts.','This helps you make ambitious client recommendations without overstating what the evidence supports.',array['sales_client','consulting'],array['make_recommendations','communicate_with_confidence'],3),

('v014_mgr_delegation','management','The work keeps coming back to you','A capable team member keeps escalating routine decisions for your approval. Delivery is slowing, but mistakes would have visible consequences. What would you do next?','["Take the decisions back permanently because you can make them faster","Clarify decision boundaries, define what needs escalation, agree checks for higher-risk cases, and let them own the rest","Tell them to be more confident without changing anything else","Approve everything quickly so the team does not wait"]','triage','{}',1,'1',64,'Management • Delegation','delegation','decision-uncertainty','The problem is not simply confidence or speed; unclear boundaries can create both over-escalation and risk.','Delegate decisions with explicit boundaries, feedback and escalation rules.','This improves judgement through other people rather than turning the manager into the permanent bottleneck.',array['people_hr','operations'],array['people_decisions','prioritisation'],4),
('v014_mgr_accounts','management','Two credible versions of the same event','An employee says a deadline slipped because priorities changed repeatedly. Their project lead says they failed to flag risk early. Sort the evidence you would seek by what it can establish.','["A dated record of priority changes and agreed deadlines","Whether colleagues personally like the employee","Messages showing when risk was raised and how it was answered","The project lead’s seniority"]','classification','{"categories":[{"id":"useful","label":"Useful evidence"},{"id":"weak","label":"Weak proxy"}]}',null,'{"0":"useful","1":"weak","2":"useful","3":"weak"}',65,'Management • Conflicting accounts','performance management','evidence-evaluation','A fair management judgement needs evidence about expectations, changes and communication, not status or popularity.','Reconstruct what happened before deciding what it says about the person.','This reduces the risk that a confident narrative becomes a performance decision without enough evidence.',array['people_hr'],array['people_decisions','managing_risk'],4),
('v014_mgr_kpi','management','The metric people learned to game','A bonus metric rewards cases closed per day. Closures rise, but reopened cases and customer complaints rise too. What would you do next?','["Increase the target because the team has proved it can close more cases","Remove all metrics because incentives always distort behaviour","Redesign the measure to include quality/outcomes, inspect the behaviour it created, and decide whether the incentive still serves the real objective","Keep the metric but ask managers to use judgement informally"]','triage','{}',2,'2',67,'Management • Incentive scheme','KPI gaming','problem-framing','People optimised the measure while the underlying outcome worsened.','Manage the objective and system effects, not just the metric used as a proxy.','This is managerial judgement about incentives: the scorecard changes behaviour, so its side effects are part of the decision.',array['people_hr','operations'],array['organisational_performance','people_decisions'],5),
('v014_mgr_change','management','Adoption is not attendance','A new process has 95% training attendance but weak real-world adoption. Rank the questions to investigate.','["What prevents people using it in the actual workflow—time, incentives, usability, capability or local workarounds?","Did everyone receive the training invite?","Which teams are adopting it and what is different about their work or management environment?","Can we make the training slides more colourful?"]','ranking','{}',null,'[0,2,1,3]',65,'Management • Change adoption','leading change','missing-information','Attendance is an input; adoption depends on whether behaviour changes in the work environment.','Look for the constraint in the real system before prescribing more of the same intervention.','This helps managers distinguish “we delivered the change activity” from “the organisation changed”.',array['operations','people_hr'],array['leading_change','organisational_performance'],4),
('v014_mgr_resources','management','What do you stop?','Three initiatives are individually valuable, but your team can deliver only two without sustained overtime. What would you do next?','["Ask the team to start all three and see which slips","Rank initiatives using strategic value, consequence of delay, capacity demand and dependencies, then explicitly stop or defer one","Choose the newest initiative because expectations are highest","Choose the oldest because sunk effort must be protected"]','triage','{}',1,'1',66,'Management • Resource allocation','prioritisation','decision-uncertainty','The management decision is not how to squeeze in all demand; it is how to make the trade-off explicit.','When capacity is constrained, deciding what not to do is part of responsible prioritisation.','This protects delivery and morale while making stakeholder trade-offs visible rather than pushing them into hidden overtime.',array['operations','strategy'],array['prioritisation','resource_allocation'],4),

('v014_exec_ma','executive','The acquisition that only works at full synergy','An acquisition is value-accretive only if 90% of projected synergies arrive within two years, while integration would consume scarce leadership capacity. What would you do next?','["Approve because the headline IRR clears the hurdle rate","Reject because integration always destroys value","Test the value case under slower/lower synergy capture, quantify leadership opportunity cost, and identify which assumptions would trigger a walk-away or revised price","Ask the deal team to increase the synergy estimate so there is more buffer"]','triage','{}',2,'2',73,'Executive • Acquisition','M&A','decision-uncertainty','The decision depends on the distribution and dependency of value, not merely the base-case IRR.','Stress the assumptions that carry value and include the opportunity cost imposed on the wider portfolio.','This turns deal conviction into a decision that is robust to integration reality and alternative uses of capital.',array['strategy','finance_commercial'],array['capital_allocation','strategy'],6),
('v014_exec_crisis','executive','The first hour of a reputational crisis','A serious product allegation is spreading rapidly online. Facts are incomplete; silence may look evasive, but a wrong statement could deepen the problem. Rank the priorities.','["Establish verified facts, decision ownership and the next time the organisation will update stakeholders","Publish a definitive denial immediately to stop the story","Protect people/customers from any plausible ongoing harm while investigation continues","Coordinate legal, operational and communications implications before making claims that cannot be withdrawn"]','ranking','{}',null,'[2,0,3,1]',74,'Executive • Crisis response','crisis decision','decision-uncertainty','In a crisis, action and communication must handle asymmetric harms while the fact base is still moving.','Prioritise irreversible harm, verified facts and clear decision ownership before narrative control.','Executive judgement under pressure is often about sequencing actions when neither delay nor premature certainty is cost-free.',array['strategy','legal_compliance'],array['governance_risk','organisational_performance'],6),
('v014_exec_incentives','executive','What will the organisation optimise?','A new executive incentive plan heavily rewards annual revenue growth. Sort each possible consequence as aligned outcome or incentive risk.','["Greater focus on profitable growth where margin gates also apply","Discount-heavy deals that pull revenue forward","Investment in customer retention that improves durable economics","Deferring necessary restructuring because it would reduce current-year revenue"]','classification','{"categories":[{"id":"aligned","label":"Potentially aligned"},{"id":"risk","label":"Incentive risk"}]}',null,'{"0":"aligned","1":"risk","2":"aligned","3":"risk"}',73,'Executive • Incentive design','organisational incentives','bias-recognition','Measures do not merely observe behaviour; incentives change what the organisation optimises.','Judge an incentive partly by the behaviours it can rationally create at the edges.','This is system-level judgement: the design can alter decisions across the organisation long after the board meeting ends.',array['strategy','people_hr'],array['organisational_performance','governance_risk'],6),
('v014_exec_capital','executive','Three uses of the same capital','You can fund a proven core expansion, a high-upside uncertain new capability, or debt reduction that materially strengthens resilience. What would you do next?','["Fund the project with the highest standalone forecast return","Compare risk-adjusted value, strategic options, balance-sheet constraints, concentration and what each choice prevents you doing, then choose the portfolio trade-off","Split the money equally to avoid choosing","Always prioritise debt reduction because it is the least uncertain"]','triage','{}',1,'1',75,'Executive • Capital allocation','portfolio capital','decision-uncertainty','Capital allocation is a portfolio choice: each commitment changes resilience, concentration and future options.','Compare opportunities on consistent criteria and include the option value and opportunity cost of commitment.','This is executive judgement about the portfolio, not merely project-by-project approval.',array['strategy','finance_commercial'],array['capital_allocation','strategy'],6),
('v014_exec_ai_governance','executive','Where should AI be allowed to act?','A proposed AI operating model would automate decisions across the group. Choose the TWO design principles that matter most at executive level.','["Set human oversight and escalation in proportion to consequence, reversibility and ability to verify","Use one universal confidence threshold for every AI decision so governance is consistent","Keep accountable human owners for high-impact decisions and monitor outcomes, not just model accuracy","Require executives to approve every AI-generated email"]','multi_select','{}',null,'[0,2]',72,'Executive • AI operating model','AI governance','ai-trust-boundaries','Good governance changes with consequence and preserves accountability where automation can create material harm.','Design the human-AI boundary around consequence, reversibility, verification and accountable ownership.','This makes AI governance an operating-model decision rather than a blanket ban or blanket permission.',array['strategy','technology_engineering'],array['ai_and_technology','governance_risk'],5);

insert into public.challenges(id,content_key,title,prompt,options,challenge_type,difficulty,is_diagnostic,confidence_required,is_published,sort_order,interaction_type,interaction_config,audience_segments,scenario_context,scenario_category,function_tags,goal_tags,complexity_level)
select gen_random_uuid(),content_key,title,prompt,options,'audience_depth',difficulty,false,true,true,3000+row_number() over(order by audience,content_key),interaction_type,interaction_config,array[audience],scenario,category,function_tags,goal_tags,complexity
from tmp_v014_curated_challenge s where not exists(select 1 from public.challenges c where c.content_key=s.content_key);

insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns)
select c.id,s.correct_index,s.correct_answer,s.explanation,s.principle,s.application,'{}'::jsonb
from tmp_v014_curated_challenge s join public.challenges c on c.content_key=s.content_key
where not exists(select 1 from public.challenge_answer_keys k where k.challenge_id=c.id);

insert into public.challenge_skill_mapping(challenge_id,skill_id,weight)
select c.id,sk.id,1 from tmp_v014_curated_challenge s join public.challenges c on c.content_key=s.content_key join public.skills sk on sk.slug=s.skill_slug
where not exists(select 1 from public.challenge_skill_mapping m where m.challenge_id=c.id);
